discrete DataCollectionSystem
port:
    event input real ExternalTrigger;
    event input real ErrorSignal;
    event output real DataCollected;
state:
    initial state Initialization
        when entry() then
            statehold(0);
        end;
        when receive(ExternalTrigger) then
            transition(DataCollection);
        end;
    end;

    state DataCollection
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(Initialization);
            out
                send(DataCollected, 1);
        end;
        when receive(ErrorSignal) then
            transition(ErrorHandling);
        end;
    end;

    state ErrorHandling
        when entry() then
            statehold(2);
        end;
        when timeover() then
            transition(Initialization);
        end;
    end;
end;
end;

discrete SignalProcessingSystem
port:
    event input real CompleteDataPacket;
    event input real AbnormalSignal;
    event output real ProcessedData;
state:
    initial state Initialization
        when entry() then
            statehold(0);
        end;
        when receive(CompleteDataPacket) then
            transition(DataProcessing);
        end;
    end;

    state DataProcessing
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(Initialization);
            out
                send(ProcessedData, 1);
        end;
        when receive(AbnormalSignal) then
            transition(ExceptionHandling);
        end;
    end;

    state ExceptionHandling
        when entry() then
            statehold(3);
        end;
        when timeover() then
            transition(Initialization);
        end;
    end;
end;
end;

discrete OutputControlSystem
port:
    event input real ProcessedDataReceived;
    event input real BlockageSignal;
    event output real OutputCompleted;
state:
    initial state Initialization
        when entry() then
            statehold(0);
        end;
        when receive(ProcessedDataReceived) then
            transition(Output);
        end;
    end;

    state Output
        when entry() then
            statehold(2);
        end;
        when timeover() then
            transition(Initialization);
            out
                send(OutputCompleted, 1);
        end;
        when receive(BlockageSignal) then
            transition(BlockageHandling);
        end;
    end;

    state BlockageHandling
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(Output);
        end;
        when receive(BlockageSignal) then
            transition(Initialization);
        end;
    end;
end;
end;

couple SystemConnection
import architectureModels.DataCollectionSystem as DCS;
import architectureModels.SignalProcessingSystem as SPS;
import architectureModels.OutputControlSystem as OCS;
part:
    DCS DataCollectionInstance;
    SPS SignalProcessingInstance;
    OCS OutputControlInstance;
connection:
    connect(DataCollectionInstance.DataCollected, SignalProcessingInstance.CompleteDataPacket);
    connect(SignalProcessingInstance.ProcessedData, OutputControlInstance.ProcessedDataReceived);
end;
